import {getAll,getOne,putOne,deleteOne,bulkPut,uid,logEvent,getSetting,setSetting,exportAll,resetAll} from './db.js';
import {fuzzySearch} from './search.js';
import {getMetadata,checkHealth,makeSnapshot} from './metadata.js';
import {signIn,signUp,pullCloud,pushCloud} from './cloud.js';

const $=(q,r=document)=>r.querySelector(q), $$=(q,r=document)=>[...r.querySelectorAll(q)];
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmtDate=t=>new Intl.DateTimeFormat('th-TH',{dateStyle:'medium',timeStyle:'short'}).format(new Date(t));
const state={page:'home',links:[],collections:[],events:[],archives:[],workspaces:[],settings:{interfaceGlow:true,autoMetadata:true,aiEnabled:true,compactCards:false,brokenScan:true,autoSnapshot:false,workerUrl:'',supabaseUrl:'',supabaseAnonKey:'',cloudSession:null},undo:null,deferredInstall:null};
const pageMeta={home:['Library','Home'],search:['Discovery','Search'],favorites:['Library','Favorites'],collections:['Organization','Collections'],workspaces:['Collaboration','Workspaces'],analytics:['Insights','Analytics'],health:['Diagnostics','Link Health'],archive:['Memory','Archive'],'import-export':['System','Import / Export'],settings:['System','Settings']};

async function bootstrap(){await loadState();await seedCollections();await refreshState();bindShell();registerPWA();navigate(location.hash.slice(1)||'home',false);updateSidebarStats()}
async function loadState(){const defaults=state.settings;for(const k of Object.keys(defaults)){state.settings[k]=await getSetting(k,defaults[k])}}
async function refreshState(){[state.links,state.collections,state.events,state.archives,state.workspaces]=await Promise.all(['links','collections','events','archives','workspaces'].map(getAll));state.links.sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));updateSidebarStats()}
async function seedCollections(){const cols=await getAll('collections');if(cols.length)return;await bulkPut('collections',[{id:'col_ai',name:'AI & Research',icon:'brain',createdAt:Date.now()},{id:'col_dev',name:'Development',icon:'code',createdAt:Date.now()},{id:'col_inbox',name:'Inbox',icon:'tray',createdAt:Date.now()}])}
function updateSidebarStats(){if(!$('#side-links'))return;$('#side-links').textContent=state.links.length;$('#side-favs').textContent=state.links.filter(x=>x.favorite).length;$('#side-cols').textContent=state.collections.length;const pill=$('#sync-pill');const cloud=!!state.settings.cloudSession?.access_token;pill.className=`status-pill ${cloud?'cloud':'local'}`;pill.innerHTML=`<span></span>${cloud?'Cloud':'Local'}`}
function bindShell(){$('#sidebar-nav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)navigate(b.dataset.page)});$('.brand-button').addEventListener('click',()=>navigate('home'));$('#mobile-menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#add-link-btn').onclick=()=>showAddModal();$('#command-btn').onclick=openCommand;window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)||'home',false));document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand()}if(e.key==='Escape'){closeModal();closeCommand()}});$('#command-overlay').addEventListener('click',e=>{if(e.target===e.currentTarget)closeCommand()});$('#import-file').addEventListener('change',handleImportFile)}
function navigate(page,push=true){if(!pageMeta[page])page='home';state.page=page;if(push)location.hash=page;const [eye,title]=pageMeta[page];$('#page-eyebrow').textContent=eye;$('#page-title').textContent=title;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#sidebar').classList.remove('open');renderPage()}
async function renderPage(){await refreshState();const root=$('#dynamic-content');const map={home:renderHome,search:renderSearch,favorites:renderFavorites,collections:renderCollections,workspaces:renderWorkspaces,analytics:renderAnalytics,health:renderHealth,archive:renderArchive,'import-export':renderImportExport,settings:renderSettings};root.innerHTML=await map[state.page]();bindPage(state.page)}
function hero(chip,title,desc,actions=''){return `<section class="page-hero rounded-3xl p-6 md:p-8"><div class="relative z-[2] flex flex-col md:flex-row md:items-end justify-between gap-5"><div><span class="soft-chip mb-4">${chip}</span><h2 class="text-2xl md:text-3xl font-semibold text-white tracking-tight">${title}</h2><p class="text-xs md:text-sm text-slate-500 mt-2 max-w-2xl leading-6">${desc}</p></div>${actions}</div></section>`}
function healthClass(s){return s==='ok'?'health-ok':s==='broken'?'health-broken':s==='redirect'?'health-redirect':'health-unknown'}
function card(link,{draggable=false}={}){const col=state.collections.find(c=>c.id===link.collectionId);const img=link.imageUrl?`<img src="${esc(link.imageUrl)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()">`:`<div class="absolute inset-0 bg-gradient-to-br from-blue-950 via-slate-900 to-violet-950"></div>`;return `<article class="link-card ${state.settings.compactCards?'compact':''}" data-link-id="${link.id}" ${draggable?'draggable="true"':''}><div class="preview">${img}<div class="absolute z-[3] left-3 bottom-3 right-12"><p class="text-[9px] text-cyan-200/70 uppercase tracking-widest">${esc(link.category||'General')}</p><h3 class="text-white font-semibold text-sm line-clamp-2 mt-1">${esc(link.title||link.domain)}</h3></div><div class="link-menu flex gap-1"><button class="card-action favorite-btn ${link.favorite?'active':''}" data-action="favorite"><i class="${link.favorite?'ph-fill':'ph'} ph-star"></i></button><button class="card-action" data-action="edit"><i class="ph ph-pencil-simple"></i></button></div></div><div class="p-3.5"><div class="flex gap-3 items-start"><div class="favicon shrink-0">${link.favicon?`<img src="${esc(link.favicon)}" alt="">`:`<i class="ph ph-link"></i>`}</div><div class="min-w-0 flex-1"><div class="flex items-center gap-2"><span class="health-dot ${healthClass(link.health?.state)}"></span><p class="text-[10px] text-slate-500 truncate">${esc(link.domain||new URL(link.url).hostname)}</p></div><p class="text-[10px] text-slate-400 line-clamp-2 mt-1.5 leading-4 min-h-8">${esc(link.summary||link.description||'No description')}</p></div></div><div class="flex flex-wrap gap-1 mt-3">${(link.tags||[]).slice(0,4).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}${col?`<span class="tag text-cyan-300/70"><i class="ph ph-folder"></i> ${esc(col.name)}</span>`:''}</div></div></article>`}
function metric(label,value,meta,icon){return `<div class="metric holo-card"><div class="flex items-center justify-between"><div class="label">${label}</div><i class="ph ph-${icon} text-cyan-300/55"></i></div><div class="value">${value}</div><div class="meta">${meta}</div></div>`}
function empty(icon,title,desc){return `<div class="col-span-full holo-card rounded-2xl p-10 text-center"><i class="ph ph-${icon} text-4xl text-slate-700"></i><h3 class="text-white text-sm mt-4">${title}</h3><p class="text-[10px] text-slate-600 mt-2">${desc}</p></div>`}

async function renderHome(){const recent=state.links.slice(0,12);return `<div class="page-shell space-y-6">${hero('<i class="ph-fill ph-sparkle"></i> Smart capture','Your web, remembered intelligently.','Paste any URL. Smart Link Hub stores it locally, extracts a preview, removes duplicates, categorizes it and keeps it searchable — even after refresh.')}<section class="holo-card rounded-3xl p-4 md:p-5"><div class="relative max-w-4xl mx-auto"><i class="ph ph-link-simple absolute left-4 top-1/2 -translate-y-1/2 text-cyan-300 text-lg"></i><input id="url-input" class="magic-input" placeholder="Paste URL or type one here…" autocomplete="off"><button id="save-url-btn" class="absolute right-2 top-1/2 -translate-y-1/2 primary-btn"><i class="ph ph-sparkle"></i><span class="hidden sm:inline">Smart Save</span></button></div><div class="flex flex-wrap justify-center gap-2 mt-4"><span class="soft-chip"><i class="ph ph-database"></i> IndexedDB</span><span class="soft-chip"><i class="ph ph-copy"></i> Duplicate guard</span><span class="soft-chip"><i class="ph ph-brain"></i> Smart summary</span><span class="soft-chip"><i class="ph ph-cloud"></i> Optional cloud sync</span></div></section><div class="grid grid-cols-2 xl:grid-cols-4 gap-3">${metric('Total links',state.links.length,'Saved permanently','link')}${metric('Favorites',state.links.filter(x=>x.favorite).length,'Persistent stars','star')}${metric('Collections',state.collections.length,'Drag & drop ready','folders')}${metric('Needs review',state.links.filter(x=>['broken','unknown'].includes(x.health?.state||'unknown')).length,'Health status','heartbeat')}</div><section><div class="flex items-end justify-between mb-3"><div><h3 class="text-white font-semibold text-sm">Recent links</h3><p class="text-[10px] text-slate-600 mt-1">Newest items in your local library</p></div><button data-go="search" class="secondary-btn">Search all <i class="ph ph-arrow-right"></i></button></div><div class="grid sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-4">${recent.length?recent.map(x=>card(x,{draggable:true})).join(''):empty('link','No links yet','Paste your first URL above. It will remain here after refresh.')}</div></section></div>`}
async function renderSearch(){return `<div class="page-shell space-y-6">${hero('<i class="ph-fill ph-magnifying-glass"></i> Fuzzy engine','Search everything, not just titles.','Matches title, URL, description, category and tags. Typo-tolerant scoring ranks the closest results first.')}<div class="holo-card rounded-2xl p-4"><div class="relative"><i class="ph ph-magnifying-glass absolute left-4 top-1/2 -translate-y-1/2 text-cyan-300"></i><input id="search-input" class="magic-input" placeholder="Search title, URL, description, tag or category…"><span id="search-count" class="absolute right-4 top-1/2 -translate-y-1/2 text-[9px] text-slate-600">${state.links.length} items</span></div></div><div id="search-results" class="grid sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-4">${state.links.length?state.links.map(x=>card(x)).join(''):empty('magnifying-glass','Nothing to search yet','Save a few links first.')}</div></div>`}
async function renderFavorites(){const rows=state.links.filter(x=>x.favorite);return `<div class="page-shell space-y-6">${hero('<i class="ph-fill ph-star"></i> Star vault','Favorites that stay favorite.','Favorite state is persisted in IndexedDB, so your starred links survive refresh, browser restarts and offline use.')}<div class="grid sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-4">${rows.length?rows.map(x=>card(x)).join(''):empty('star','No favorites yet','Tap the star on any link to pin it here.')}</div></div>`}
async function renderCollections(){return `<div class="page-shell space-y-6">${hero('<i class="ph-fill ph-folders"></i> Smart folders','Organize by dragging, not by typing.','Drag any link card onto a collection below. Changes are persisted immediately.',`<button id="new-collection" class="primary-btn"><i class="ph ph-plus"></i> New collection</button>`)}<div class="grid md:grid-cols-2 xl:grid-cols-3 gap-4">${state.collections.map(c=>{const rows=state.links.filter(x=>x.collectionId===c.id);return `<section class="collection-drop holo-card rounded-2xl p-4 min-h-44" data-collection-id="${c.id}"><div class="flex items-center justify-between"><div class="flex items-center gap-3"><div class="w-9 h-9 grid place-items-center rounded-xl bg-cyan-400/[.06] text-cyan-300"><i class="ph ph-${esc(c.icon||'folder')}"></i></div><div><h3 class="text-white text-sm font-medium">${esc(c.name)}</h3><p class="text-[9px] text-slate-600">${rows.length} links</p></div></div><button class="card-action" data-edit-collection="${c.id}"><i class="ph ph-dots-three"></i></button></div><div class="mt-4 space-y-2">${rows.slice(0,4).map(x=>`<div draggable="true" data-link-id="${x.id}" class="rounded-xl border border-white/[.05] bg-white/[.02] px-3 py-2 flex items-center gap-2 cursor-grab"><span class="health-dot ${healthClass(x.health?.state)}"></span><span class="text-[10px] text-slate-400 truncate">${esc(x.title)}</span></div>`).join('')||'<div class="h-20 grid place-items-center border border-dashed border-white/[.06] rounded-xl text-[9px] text-slate-700">Drop links here</div>'}</div></section>`}).join('')}</div><section><div class="flex items-center justify-between mb-3"><h3 class="text-white text-sm font-semibold">Unsorted / all links</h3><span class="soft-chip">Drag cards into folders</span></div><div class="grid sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-4">${state.links.map(x=>card(x,{draggable:true})).join('')||empty('folders','No links','Add links from Home first.')}</div></section></div>`}
async function renderWorkspaces(){const cloud=!!state.settings.cloudSession?.access_token;return `<div class="page-shell space-y-6">${hero('<i class="ph-fill ph-users-three"></i> Shared spaces','Workspaces with permission-ready sync.','Workspaces work locally now. When Supabase is connected, the included RLS schema supports owner/editor/viewer membership.',`<button id="new-workspace" class="primary-btn"><i class="ph ph-plus"></i> New workspace</button>`)}<div class="holo-card rounded-2xl p-5 flex items-center justify-between"><div><p class="text-white text-sm font-medium">Cloud collaboration</p><p class="text-[10px] text-slate-600 mt-1">${cloud?'Authenticated. Push or pull the shared dataset.':'Local mode. Connect Supabase in Settings to sync across devices.'}</p></div><div class="flex gap-2">${cloud?'<button id="cloud-pull" class="secondary-btn"><i class="ph ph-download"></i> Pull</button><button id="cloud-push" class="primary-btn"><i class="ph ph-upload"></i> Push</button>':'<button data-go="settings" class="secondary-btn">Connect</button>'}</div></div><div class="grid md:grid-cols-2 xl:grid-cols-3 gap-4">${state.workspaces.length?state.workspaces.map(w=>`<div class="holo-card rounded-2xl p-5"><div class="flex justify-between"><div class="w-10 h-10 rounded-xl grid place-items-center bg-violet-500/10 text-violet-300"><i class="ph ph-users-three"></i></div><span class="soft-chip">${esc(w.role||'owner')}</span></div><h3 class="text-white font-semibold mt-5">${esc(w.name)}</h3><p class="text-[10px] text-slate-600 mt-1">${esc(w.description||'Shared link workspace')}</p><div class="mt-4 text-[9px] text-slate-500">${w.members?.length||1} member(s) · ${w.collectionIds?.length||0} collection(s)</div></div>`).join(''):empty('users-three','No workspace yet','Create one for a project, team or shared research list.')}</div></div>`}
function analyticsData(){const now=Date.now(),days=[];for(let i=6;i>=0;i--){const d=new Date(now-i*864e5),key=d.toISOString().slice(0,10);days.push({key,label:new Intl.DateTimeFormat('th-TH',{weekday:'short'}).format(d),count:state.events.filter(e=>new Date(e.at).toISOString().slice(0,10)===key).length})}const types={};state.events.forEach(e=>types[e.type]=(types[e.type]||0)+1);const cats={};state.links.forEach(l=>cats[l.category||'General']=(cats[l.category||'General']||0)+1);return {days,types,cats}}
async function renderAnalytics(){const a=analyticsData(),max=Math.max(1,...a.days.map(x=>x.count)),opened=a.types.open||0,saved=a.types.save||0;return `<div class="page-shell space-y-6">${hero('<i class="ph-fill ph-chart-line-up"></i> Live telemetry','Analytics from your actual activity.','Every save, open, favorite, search and cleanup event is recorded locally. No demo numbers.')}<div class="grid grid-cols-2 xl:grid-cols-4 gap-3">${metric('Saved',saved,'Real save events','floppy-disk')}${metric('Opened',opened,'Real click events','cursor-click')}${metric('Favorites',state.links.filter(x=>x.favorite).length,'Current state','star')}${metric('Archives',state.archives.length,'Saved snapshots','archive')}</div><div class="grid xl:grid-cols-[1.5fr_.8fr] gap-4"><section class="holo-card rounded-2xl p-5"><div class="flex justify-between"><div><h3 class="text-white text-sm font-semibold">7-day activity</h3><p class="text-[9px] text-slate-600 mt-1">All tracked local events</p></div><span class="soft-chip">${state.events.length} events</span></div><div class="chart-bars mt-6">${a.days.map(d=>`<div class="flex-1 h-full flex flex-col justify-end items-center gap-2"><div class="chart-bar w-full" style="height:${Math.max(3,d.count/max*100)}%" title="${d.count}"></div><span class="text-[8px] text-slate-700">${d.label}</span></div>`).join('')}</div></section><section class="holo-card rounded-2xl p-5"><h3 class="text-white text-sm font-semibold">Categories</h3><div class="space-y-4 mt-5">${Object.entries(a.cats).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([k,v])=>`<div><div class="flex justify-between text-[9px]"><span class="text-slate-400">${esc(k)}</span><span class="text-slate-600">${v}</span></div><div class="h-1.5 rounded-full bg-white/[.04] mt-2 overflow-hidden"><div class="h-full bg-gradient-to-r from-blue-500/70 to-cyan-300/70" style="width:${state.links.length?v/state.links.length*100:0}%"></div></div></div>`).join('')||'<p class="text-[10px] text-slate-700">No data yet.</p>'}</div></section></div></div>`}
async function renderHealth(){const rows=[...state.links].sort((a,b)=>{const rank={broken:0,unknown:1,redirect:2,ok:3};return (rank[a.health?.state]??1)-(rank[b.health?.state]??1)});const counts=s=>rows.filter(x=>(x.health?.state||'unknown')===s).length;return `<div class="page-shell space-y-6">${hero('<i class="ph-fill ph-heartbeat"></i> Diagnostics','Link Health Center.','Scan saved URLs for reachable, redirect, broken or CORS-unknown states. Backend mode provides the most reliable checks.',`<button id="scan-all" class="primary-btn"><i class="ph ph-pulse"></i> Scan all</button>`)}<div class="grid grid-cols-2 xl:grid-cols-4 gap-3">${metric('Healthy',counts('ok'),'Responding normally','check-circle')}${metric('Redirects',counts('redirect'),'Final URL changed','arrow-bend-up-right')}${metric('Broken',counts('broken'),'Error response','warning-circle')}${metric('Unknown',counts('unknown'),'Not checked / CORS','question')}</div><div class="holo-card rounded-2xl overflow-hidden"><div class="overflow-x-auto"><table class="w-full text-left"><thead class="text-[9px] text-slate-600 uppercase tracking-wider border-b border-white/[.05]"><tr><th class="p-4">Status</th><th class="p-4">Link</th><th class="p-4">HTTP</th><th class="p-4">Checked</th><th class="p-4"></th></tr></thead><tbody>${rows.map(l=>`<tr class="border-b border-white/[.035] hover:bg-white/[.015]"><td class="p-4"><span class="health-dot ${healthClass(l.health?.state)}"></span> <span class="text-[9px] text-slate-500">${esc(l.health?.state||'unknown')}</span></td><td class="p-4"><p class="text-[10px] text-white max-w-[360px] truncate">${esc(l.title)}</p><p class="text-[9px] text-slate-700 max-w-[360px] truncate mt-1">${esc(l.url)}</p></td><td class="p-4 text-[10px] text-slate-500">${l.health?.status??'—'}</td><td class="p-4 text-[9px] text-slate-600">${l.health?.checkedAt?fmtDate(l.health.checkedAt):'Never'}</td><td class="p-4"><button data-check-one="${l.id}" class="secondary-btn">Check</button></td></tr>`).join('')||'<tr><td colspan="5" class="p-10 text-center text-slate-700 text-xs">No links yet.</td></tr>'}</tbody></table></div></div></div>`}
async function renderArchive(){return `<div class="page-shell space-y-6">${hero('<i class="ph-fill ph-archive"></i> Snapshots','Keep context even when pages change.','Manual or automatic snapshots preserve title, summary, preview and—when a Worker is configured—a text/HTML excerpt fetched at capture time.')}<div class="grid sm:grid-cols-2 xl:grid-cols-3 gap-4">${state.archives.length?state.archives.sort((a,b)=>b.capturedAt-a.capturedAt).map(a=>`<article class="holo-card rounded-2xl overflow-hidden">${a.imageUrl?`<div class="h-32 bg-slate-950"><img src="${esc(a.imageUrl)}" class="w-full h-full object-cover opacity-70" alt=""></div>`:''}<div class="p-4"><div class="flex justify-between gap-3"><div><p class="text-[9px] text-cyan-300/60 uppercase tracking-widest">${esc(a.type||'snapshot')}</p><h3 class="text-white text-sm font-medium mt-1">${esc(a.title)}</h3></div><button data-delete-archive="${a.id}" class="card-action"><i class="ph ph-trash"></i></button></div><p class="text-[10px] text-slate-500 line-clamp-3 mt-3 leading-4">${esc(a.excerpt||a.description||'')}</p><div class="flex justify-between mt-4 text-[8px] text-slate-700"><span>${fmtDate(a.capturedAt)}</span><a href="${esc(a.url)}" target="_blank" rel="noopener" class="text-cyan-400">Original ↗</a></div></div></article>`).join(''):empty('archive','No snapshots yet','Open Edit on a link and choose Create snapshot.')}</div></div>`}
async function renderImportExport(){return `<div class="page-shell space-y-6">${hero('<i class="ph-fill ph-arrows-down-up"></i> Data port','Your data stays portable.','Import browser bookmarks, JSON or CSV. Export a complete backup as JSON, CSV, browser HTML or ZIP.')}<div class="grid lg:grid-cols-2 gap-4"><section class="holo-card rounded-2xl p-6"><div class="w-10 h-10 rounded-xl grid place-items-center bg-cyan-400/[.07] text-cyan-300"><i class="ph ph-upload-simple text-xl"></i></div><h3 class="text-white text-lg font-semibold mt-5">Import</h3><p class="text-[10px] text-slate-600 mt-2">Duplicates are merged by normalized URL.</p><button id="choose-import" class="secondary-btn w-full mt-6 py-4 border-dashed"><i class="ph ph-file-arrow-up"></i> Choose HTML / JSON / CSV</button></section><section class="holo-card rounded-2xl p-6"><div class="w-10 h-10 rounded-xl grid place-items-center bg-violet-400/[.07] text-violet-300"><i class="ph ph-download-simple text-xl"></i></div><h3 class="text-white text-lg font-semibold mt-5">Export</h3><p class="text-[10px] text-slate-600 mt-2">Generated entirely in your browser.</p><div class="grid grid-cols-2 gap-2 mt-6">${[['JSON','brackets-curly'],['CSV','table'],['HTML','browser'],['ZIP','file-zip']].map(([x,i])=>`<button data-export="${x.toLowerCase()}" class="secondary-btn py-4"><i class="ph ph-${i}"></i> ${x}</button>`).join('')}</div></section></div></div>`}
function settingToggle(key,title,desc,on){return `<div class="holo-card rounded-2xl p-5 flex items-center justify-between gap-5"><div><h3 class="text-white text-sm font-medium">${title}</h3><p class="text-[9px] text-slate-600 mt-1">${desc}</p></div><button class="toggle ${on?'on':''}" data-setting="${key}" aria-pressed="${!!on}"><span></span></button></div>`}
async function renderSettings(){const s=state.settings;return `<div class="page-shell space-y-6">${hero('<i class="ph-fill ph-gear-six"></i> Control center','Real settings with real effects.','Preferences are persisted locally and immediately affect cards, metadata, snapshots, health scanning and cloud integration.')}<div class="grid xl:grid-cols-[1fr_1fr] gap-4"><section class="space-y-3">${settingToggle('interfaceGlow','Interface glow','Animated ambient lighting and motion.',s.interfaceGlow)}${settingToggle('autoMetadata','Auto metadata','Fetch title, preview image and description on save.',s.autoMetadata)}${settingToggle('aiEnabled','Smart summary & tags','Use Worker AI when configured; heuristic fallback otherwise.',s.aiEnabled)}${settingToggle('compactCards','Compact cards','Show more links per screen.',s.compactCards)}${settingToggle('brokenScan','Health scan','Enable link-health tools.',s.brokenScan)}${settingToggle('autoSnapshot','Auto snapshot','Capture an archive record after every successful save.',s.autoSnapshot)}</section><section class="space-y-3"><div class="holo-card rounded-2xl p-5"><h3 class="text-white text-sm font-semibold">Cloudflare Worker</h3><p class="text-[9px] text-slate-600 mt-1">Improves metadata, AI, health checks and snapshots.</p><div class="field mt-4"><label>Worker URL</label><input id="worker-url" value="${esc(s.workerUrl||'')}" placeholder="https://smart-link-api.your-subdomain.workers.dev"></div><button id="save-worker" class="secondary-btn mt-3">Save endpoint</button></div><div class="holo-card rounded-2xl p-5"><div class="flex justify-between"><div><h3 class="text-white text-sm font-semibold">Supabase cloud sync</h3><p class="text-[9px] text-slate-600 mt-1">Optional login and cross-device sync.</p></div><span class="status-pill ${s.cloudSession?'cloud':'local'}"><span></span>${s.cloudSession?'Signed in':'Offline'}</span></div><div class="field mt-4"><label>Project URL</label><input id="supabase-url" value="${esc(s.supabaseUrl||'')}" placeholder="https://xxxx.supabase.co"></div><div class="field mt-3"><label>Anon key</label><input id="supabase-key" type="password" value="${esc(s.supabaseAnonKey||'')}" placeholder="public anon key"></div><div class="grid grid-cols-2 gap-2 mt-3"><button id="save-cloud-config" class="secondary-btn">Save config</button><button id="cloud-auth" class="primary-btn">${s.cloudSession?'Sign out':'Sign in / Sign up'}</button></div></div><div class="holo-card rounded-2xl p-5 border-red-500/10"><h3 class="text-red-300 text-sm font-medium">Reset local library</h3><p class="text-[9px] text-slate-600 mt-1">Deletes local links, settings, analytics, workspaces and snapshots.</p><button id="reset-all" class="danger-btn mt-4">Reset everything</button></div></section></div></div>`}

function bindPage(page){$$('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));bindCards();if(page==='home')bindHome();if(page==='search')bindSearch();if(page==='collections')bindCollections();if(page==='workspaces')bindWorkspaces();if(page==='health')bindHealth();if(page==='archive')bindArchive();if(page==='import-export')bindImportExport();if(page==='settings')bindSettings()}
function bindCards(){$$('.link-card').forEach(el=>{const id=el.dataset.linkId;el.addEventListener('click',async e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action){e.stopPropagation();if(action==='favorite')return toggleFavorite(id);if(action==='edit')return showEditModal(id)}const l=state.links.find(x=>x.id===id);if(l){await logEvent('open',{id});window.open(l.url,'_blank','noopener,noreferrer')}});if(el.draggable)el.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/link-id',id);e.dataTransfer.effectAllowed='move'})})}
function bindHome(){const input=$('#url-input'),btn=$('#save-url-btn');const run=()=>saveURL(input.value);btn.onclick=run;input.addEventListener('keydown',e=>{if(e.key==='Enter')run()});input.addEventListener('paste',()=>{setTimeout(()=>{if(/^https?:\/\//i.test(input.value.trim()))run()},40)})}
function bindSearch(){const input=$('#search-input'),out=$('#search-results'),count=$('#search-count');input.oninput=()=>{const rows=fuzzySearch(state.links,input.value);out.innerHTML=rows.length?rows.map(x=>card(x)).join(''):empty('magnifying-glass','No match','Try a title, domain, tag or category.');count.textContent=`${rows.length} match${rows.length===1?'':'es'}`;bindCards()};input.addEventListener('change',()=>logEvent('search',{q:input.value}));input.focus()}
function bindCollections(){$('#new-collection').onclick=()=>showCollectionModal();$$('[data-edit-collection]').forEach(b=>b.onclick=()=>showCollectionModal(b.dataset.editCollection));$$('[draggable="true"][data-link-id]').forEach(x=>x.addEventListener('dragstart',e=>e.dataTransfer.setData('text/link-id',x.dataset.linkId)));$$('.collection-drop').forEach(z=>{z.addEventListener('dragover',e=>{e.preventDefault();z.classList.add('drag-over')});z.addEventListener('dragleave',()=>z.classList.remove('drag-over'));z.addEventListener('drop',async e=>{e.preventDefault();z.classList.remove('drag-over');const id=e.dataTransfer.getData('text/link-id'),link=state.links.find(x=>x.id===id);if(link){link.collectionId=z.dataset.collectionId;link.updatedAt=Date.now();await putOne('links',link);await logEvent('collection_move',{id,collectionId:link.collectionId});toast('Moved to collection');renderPage()}})})}
function bindWorkspaces(){$('#new-workspace').onclick=()=>showWorkspaceModal();$('#cloud-pull')?.addEventListener('click',cloudPull);$('#cloud-push')?.addEventListener('click',cloudPush)}
function bindHealth(){$('#scan-all').onclick=scanAll;$$('[data-check-one]').forEach(b=>b.onclick=()=>scanOne(b.dataset.checkOne,true))}
function bindArchive(){$$('[data-delete-archive]').forEach(b=>b.onclick=async()=>{await deleteOne('archives',b.dataset.deleteArchive);await refreshState();renderPage();toast('Snapshot deleted')})}
function bindImportExport(){$('#choose-import').onclick=()=>$('#import-file').click();$$('[data-export]').forEach(b=>b.onclick=()=>exportData(b.dataset.export))}
function bindSettings(){$$('.toggle[data-setting]').forEach(t=>t.onclick=async()=>{const k=t.dataset.setting,v=!state.settings[k];state.settings[k]=v;await setSetting(k,v);t.classList.toggle('on',v);t.setAttribute('aria-pressed',v);applySettings();toast(`${k} ${v?'enabled':'disabled'}`)});$('#save-worker').onclick=async()=>{state.settings.workerUrl=$('#worker-url').value.trim().replace(/\/$/,'');await setSetting('workerUrl',state.settings.workerUrl);toast('Worker endpoint saved')};$('#save-cloud-config').onclick=async()=>{state.settings.supabaseUrl=$('#supabase-url').value.trim().replace(/\/$/,'');state.settings.supabaseAnonKey=$('#supabase-key').value.trim();await setSetting('supabaseUrl',state.settings.supabaseUrl);await setSetting('supabaseAnonKey',state.settings.supabaseAnonKey);toast('Cloud config saved')};$('#cloud-auth').onclick=()=>state.settings.cloudSession?cloudSignOut():showCloudAuthModal();$('#reset-all').onclick=()=>confirmReset()}
function applySettings(){document.querySelectorAll('.ambient').forEach(x=>x.style.display=state.settings.interfaceGlow?'':'none')}

async function saveURL(raw){let url=String(raw||'').trim();if(!url)return;if(!/^https?:\/\//i.test(url))url='https://'+url;let u;try{u=new URL(url);if(!['http:','https:'].includes(u.protocol))throw 0;u.hash='';url=u.href}catch{return toast('Invalid URL')}const normalized=url.replace(/\/$/,'');const duplicate=state.links.find(l=>l.normalizedUrl===normalized||l.url.replace(/\/$/,'')===normalized);if(duplicate){toast('Already saved — opening existing item');return showEditModal(duplicate.id)}const input=$('#url-input');if(input){input.disabled=true;input.value='';input.placeholder='Reading metadata & categorizing…'}let meta={title:u.hostname,domain:u.hostname.replace(/^www\./,''),description:'',summary:'',imageUrl:'',favicon:'',category:'General',tags:['General']};if(state.settings.autoMetadata){try{meta=await getMetadata(url,state.settings)}catch(e){console.warn(e)}}const now=Date.now(),link={id:uid('lnk'),url,normalizedUrl:normalized,title:meta.title||u.hostname,domain:meta.domain||u.hostname,description:meta.description||'',summary:meta.summary||meta.description||'',imageUrl:meta.imageUrl||'',favicon:meta.favicon||'',category:meta.category||'General',tags:meta.tags||['General'],collectionId:'col_inbox',favorite:false,createdAt:now,updatedAt:now,health:{state:'unknown',status:null,checkedAt:null}};await putOne('links',link);await logEvent('save',{id:link.id,category:link.category});if(state.settings.autoSnapshot)await captureSnapshot(link.id,false);await refreshState();if(input){input.disabled=false;input.placeholder='Paste URL or type one here…'}toast('Saved with preview');renderPage()}
async function toggleFavorite(id){const l=state.links.find(x=>x.id===id);if(!l)return;l.favorite=!l.favorite;l.updatedAt=Date.now();await putOne('links',l);await logEvent('favorite',{id,value:l.favorite});await refreshState();renderPage()}
async function deleteLink(id){const link=state.links.find(x=>x.id===id);if(!link)return;await deleteOne('links',id);await logEvent('delete',{id});state.undo={link,expires:Date.now()+8000};await refreshState();closeModal();renderPage();toast(`Deleted ${link.title}`,{undo:true})}
async function undoDelete(){if(!state.undo||Date.now()>state.undo.expires)return toast('Undo expired');await putOne('links',state.undo.link);await logEvent('undo_delete',{id:state.undo.link.id});state.undo=null;await refreshState();renderPage();toast('Link restored')}
function showAddModal(){modal(`<div class="p-6"><div class="flex justify-between"><div><p class="text-[9px] text-cyan-300 uppercase tracking-widest">Smart capture</p><h2 class="text-white text-xl font-semibold mt-1">Add a link</h2></div><button class="card-action" data-close><i class="ph ph-x"></i></button></div><div class="field mt-6"><label>URL</label><input id="modal-url" placeholder="https://example.com" autofocus></div><button id="modal-save-url" class="primary-btn w-full mt-4 py-3">Fetch preview & save</button></div>`);$('#modal-save-url').onclick=async()=>{const v=$('#modal-url').value;closeModal();navigate('home');setTimeout(()=>saveURL(v),20)}}
function getRelated(link,n=5){const set=new Set([link.category,...(link.tags||[])].map(x=>String(x).toLowerCase()));return state.links.filter(x=>x.id!==link.id).map(x=>({x,s:[x.category,...(x.tags||[])].reduce((n,t)=>n+(set.has(String(t).toLowerCase())?1:0),0)})).filter(r=>r.s).sort((a,b)=>b.s-a.s).slice(0,n).map(r=>r.x)}
function showEditModal(id){const l=state.links.find(x=>x.id===id);if(!l)return;const related=getRelated(l,5);modal(`<form id="edit-form" class="p-6"><div class="flex justify-between"><div><p class="text-[9px] text-cyan-300 uppercase tracking-widest">Link editor</p><h2 class="text-white text-xl font-semibold mt-1">Edit saved link</h2></div><button type="button" class="card-action" data-close><i class="ph ph-x"></i></button></div><div class="grid md:grid-cols-2 gap-3 mt-6"><div class="field md:col-span-2"><label>Title</label><input name="title" value="${esc(l.title)}"></div><div class="field md:col-span-2"><label>URL</label><input name="url" value="${esc(l.url)}"></div><div class="field md:col-span-2"><label>Description</label><textarea name="description">${esc(l.description||'')}</textarea></div><div class="field"><label>Category</label><input name="category" value="${esc(l.category||'General')}"></div><div class="field"><label>Collection</label><select name="collectionId"><option value="">None</option>${state.collections.map(c=>`<option value="${c.id}" ${l.collectionId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field md:col-span-2"><label>Tags — comma separated</label><input name="tags" value="${esc((l.tags||[]).join(', '))}"></div><div class="field md:col-span-2"><label>Preview image URL</label><input name="imageUrl" value="${esc(l.imageUrl||'')}"></div></div><div class="flex flex-wrap gap-2 mt-5"><button class="primary-btn" type="submit"><i class="ph ph-floppy-disk"></i> Save changes</button><button id="refresh-meta" class="secondary-btn" type="button"><i class="ph ph-sparkle"></i> Refresh metadata</button><button id="snapshot-link" class="secondary-btn" type="button"><i class="ph ph-archive"></i> Snapshot</button><button id="delete-link" class="danger-btn ml-auto" type="button"><i class="ph ph-trash"></i> Delete</button></div>${related.length?`<div class="mt-6 pt-5 border-t border-white/[.06]"><p class="text-[9px] uppercase tracking-widest text-slate-600">Related links</p><div class="grid sm:grid-cols-2 gap-2 mt-3">${related.map(x=>`<button type="button" data-related="${x.id}" class="text-left p-3 rounded-xl bg-white/[.025] border border-white/[.05]"><p class="text-[10px] text-white truncate">${esc(x.title)}</p><p class="text-[8px] text-slate-600 mt-1">${esc(x.category)}</p></button>`).join('')}</div></div>`:''}</form>`);$('#edit-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),newUrl=f.get('url').trim();try{new URL(newUrl)}catch{return toast('Invalid URL')};Object.assign(l,{title:f.get('title').trim(),url:newUrl,normalizedUrl:newUrl.replace(/\/$/,''),description:f.get('description').trim(),summary:f.get('description').trim(),category:f.get('category').trim()||'General',collectionId:f.get('collectionId')||'',tags:f.get('tags').split(',').map(x=>x.trim()).filter(Boolean).slice(0,10),imageUrl:f.get('imageUrl').trim(),updatedAt:Date.now()});await putOne('links',l);await logEvent('edit',{id});closeModal();await refreshState();renderPage();toast('Changes saved')};$('#refresh-meta').onclick=async()=>{toast('Refreshing metadata…');const m=await getMetadata(l.url,state.settings);Object.assign(l,{title:m.title||l.title,description:m.description||l.description,summary:m.summary||l.summary,imageUrl:m.imageUrl||l.imageUrl,favicon:m.favicon||l.favicon,domain:m.domain||l.domain,category:m.category||l.category,tags:m.tags?.length?m.tags:l.tags,updatedAt:Date.now()});await putOne('links',l);closeModal();await refreshState();renderPage();showEditModal(id)};$('#snapshot-link').onclick=()=>captureSnapshot(id,true);$('#delete-link').onclick=()=>deleteLink(id);$$('[data-related]').forEach(b=>b.onclick=()=>{closeModal();showEditModal(b.dataset.related)})}
async function captureSnapshot(id,notify=true){const l=state.links.find(x=>x.id===id)||await getOne('links',id);if(!l)return;notify&&toast('Capturing snapshot…');const snap=await makeSnapshot(l,state.settings);await putOne('archives',{id:uid('arc'),linkId:l.id,title:l.title,url:l.url,description:l.description,imageUrl:l.imageUrl,capturedAt:Date.now(),...snap});await logEvent('snapshot',{id:l.id});await refreshState();if(notify){closeModal();toast('Snapshot archived');if(state.page==='archive')renderPage()}}
function showCollectionModal(id=''){const c=state.collections.find(x=>x.id===id);modal(`<form id="collection-form" class="p-6"><div class="flex justify-between"><h2 class="text-white text-lg font-semibold">${c?'Edit':'New'} collection</h2><button type="button" class="card-action" data-close><i class="ph ph-x"></i></button></div><div class="field mt-5"><label>Name</label><input name="name" value="${esc(c?.name||'')}"></div><div class="field mt-3"><label>Icon (Phosphor name)</label><input name="icon" value="${esc(c?.icon||'folder')}"></div><div class="flex gap-2 mt-4"><button class="primary-btn" type="submit">Save</button>${c&&!['col_ai','col_dev','col_inbox'].includes(c.id)?'<button type="button" id="delete-collection" class="danger-btn">Delete</button>':''}</div></form>`);$('#collection-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await putOne('collections',{id:c?.id||uid('col'),name:f.get('name').trim()||'Untitled',icon:f.get('icon').trim()||'folder',createdAt:c?.createdAt||Date.now(),updatedAt:Date.now()});closeModal();await refreshState();renderPage()};$('#delete-collection')?.addEventListener('click',async()=>{for(const l of state.links.filter(x=>x.collectionId===c.id)){l.collectionId='';await putOne('links',l)}await deleteOne('collections',c.id);closeModal();await refreshState();renderPage();toast('Collection deleted')})}
function showWorkspaceModal(){modal(`<form id="workspace-form" class="p-6"><div class="flex justify-between"><h2 class="text-white text-lg font-semibold">New workspace</h2><button type="button" class="card-action" data-close><i class="ph ph-x"></i></button></div><div class="field mt-5"><label>Name</label><input name="name"></div><div class="field mt-3"><label>Description</label><textarea name="description"></textarea></div><div class="field mt-3"><label>Collections</label><div class="grid grid-cols-2 gap-2">${state.collections.map(c=>`<label class="flex items-center gap-2 text-[10px] text-slate-400"><input type="checkbox" name="collections" value="${c.id}"> ${esc(c.name)}</label>`).join('')}</div></div><button class="primary-btn mt-4" type="submit">Create workspace</button></form>`);$('#workspace-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),w={id:uid('ws'),name:f.get('name').trim()||'Workspace',description:f.get('description').trim(),role:'owner',members:['local-user'],collectionIds:f.getAll('collections'),createdAt:Date.now(),updatedAt:Date.now()};await putOne('workspaces',w);await logEvent('workspace_create',{id:w.id});closeModal();await refreshState();renderPage()}}
async function scanOne(id,rerender=false){const l=state.links.find(x=>x.id===id);if(!l)return;const h=await checkHealth(l.url,state.settings);l.health=h;l.updatedAt=Date.now();await putOne('links',l);await logEvent('health_check',{id,state:h.state});if(rerender){await refreshState();renderPage();toast(`Health: ${h.state}`)}}
async function scanAll(){const btn=$('#scan-all');btn.disabled=true;btn.innerHTML='<span class="spinner"></span> Scanning';let i=0;for(const l of state.links){await scanOne(l.id,false);i++;btn.innerHTML=`<span class="spinner"></span> ${i}/${state.links.length}`}await refreshState();renderPage();toast('Health scan complete')}
function download(content,name,type='text/plain'){const blob=content instanceof Blob?content:new Blob([content],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function csvText(links){const head=['title','url','description','category','tags','favorite','collectionId','createdAt'];const q=v=>'"'+String(v??'').replaceAll('"','""')+'"';return [head.join(','),...links.map(l=>head.map(k=>q(k==='tags'?(l.tags||[]).join('|'):l[k])).join(','))].join('\n')}
async function exportData(kind){const all=await exportAll(),stamp=new Date().toISOString().slice(0,10);if(kind==='json')return download(JSON.stringify(all,null,2),`smart-link-hub-${stamp}.json`,'application/json');if(kind==='csv')return download(await csvText(all.links),`smart-link-hub-${stamp}.csv`,'text/csv');if(kind==='html'){const h=`<!DOCTYPE NETSCAPE-Bookmark-file-1><META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8"><TITLE>Smart Link Hub</TITLE><H1>Smart Link Hub</H1><DL><p>${all.links.map(l=>`<DT><A HREF="${esc(l.url)}" ADD_DATE="${Math.floor((l.createdAt||Date.now())/1000)}" TAGS="${esc((l.tags||[]).join(','))}">${esc(l.title)}</A>`).join('\n')}</DL>`;return download(h,`smart-link-hub-${stamp}.html`,'text/html')}if(kind==='zip'){if(!window.JSZip)return toast('ZIP library is still loading');const zip=new JSZip();zip.file('backup.json',JSON.stringify(all,null,2));zip.file('links.csv',await csvText(all.links));zip.file('README.txt','Smart Link Hub V3 portable backup. Import backup.json to restore the complete local dataset.');return download(await zip.generateAsync({type:'blob'}),`smart-link-hub-${stamp}.zip`,'application/zip')}}
async function handleImportFile(e){const file=e.target.files[0];if(!file)return;try{const text=await file.text();let links=[];if(/\.json$/i.test(file.name)){const j=JSON.parse(text);links=Array.isArray(j)?j:(j.links||[]);if(j.collections?.length)await bulkPut('collections',j.collections);if(j.archives?.length)await bulkPut('archives',j.archives)}else if(/\.html?$/i.test(file.name)){const doc=new DOMParser().parseFromString(text,'text/html');links=$$('a[href]',doc).map(a=>({url:a.href,title:a.textContent.trim()||new URL(a.href).hostname,tags:(a.getAttribute('tags')||'').split(',').filter(Boolean)}))}else if(/\.csv$/i.test(file.name)){links=parseCSV(text)}let added=0;for(const x of links){if(!x.url)continue;let u;try{u=new URL(x.url)}catch{continue};const normalized=u.href.replace(/\/$/,'');if(state.links.some(l=>l.normalizedUrl===normalized))continue;const tags=Array.isArray(x.tags)?x.tags:String(x.tags||'').split('|').filter(Boolean);await putOne('links',{id:x.id||uid('lnk'),url:u.href,normalizedUrl:normalized,title:x.title||u.hostname,domain:x.domain||u.hostname.replace(/^www\./,''),description:x.description||'',summary:x.summary||x.description||'',imageUrl:x.imageUrl||'',favicon:x.favicon||`https://www.google.com/s2/favicons?sz=96&domain=${u.hostname}`,category:x.category||'General',tags:tags.length?tags:[x.category||'General'],collectionId:x.collectionId||'col_inbox',favorite:String(x.favorite)==='true'||x.favorite===true,createdAt:Number(x.createdAt)||Date.now(),updatedAt:Date.now(),health:x.health||{state:'unknown'}});added++}await logEvent('import',{count:added});await refreshState();renderPage();toast(`Imported ${added} new link(s)`) }catch(err){console.error(err);toast('Import failed: '+err.message)}finally{e.target.value=''}}
function parseCSV(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&q&&n==='"'){cell+='"';i++}else if(c==='"')q=!q;else if(c===','&&!q){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&n==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}if(cell||row.length){row.push(cell);rows.push(row)}const head=(rows.shift()||[]).map(x=>x.trim());return rows.map(r=>Object.fromEntries(head.map((h,i)=>[h,r[i]||''])))}
function openCommand(){const ov=$('#command-overlay');ov.classList.remove('hidden');ov.setAttribute('aria-hidden','false');const actions=[...Object.entries(pageMeta).map(([id,m])=>({label:`Go to ${m[1]}`,icon:'arrow-right',run:()=>navigate(id)})),{label:'Add new link',icon:'plus',run:showAddModal},{label:'Create collection',icon:'folder-plus',run:()=>showCollectionModal()},{label:'Scan link health',icon:'heartbeat',run:()=>navigate('health')},{label:'Export backup',icon:'download-simple',run:()=>navigate('import-export')}];ov.innerHTML=`<div class="command-box"><input id="command-input" placeholder="Type a command or search your links…"><div id="command-list" class="command-list"></div></div>`;const input=$('#command-input'),list=$('#command-list');const draw=()=>{const q=input.value.trim();const linkRows=q?fuzzySearch(state.links,q).slice(0,8):[];const actionRows=actions.filter(a=>!q||a.label.toLowerCase().includes(q.toLowerCase())).slice(0,6);list.innerHTML=actionRows.map((a,i)=>`<button class="command-item" data-cmd-action="${i}"><i class="ph ph-${a.icon}"></i>${esc(a.label)}<small>Action</small></button>`).join('')+linkRows.map(l=>`<button class="command-item" data-cmd-link="${l.id}"><i class="ph ph-link"></i><span class="truncate">${esc(l.title)}</span><small>${esc(l.domain)}</small></button>`).join('');$$('[data-cmd-action]',list).forEach(b=>b.onclick=()=>{closeCommand();actions[+b.dataset.cmdAction].run()});$$('[data-cmd-link]',list).forEach(b=>b.onclick=async()=>{const l=state.links.find(x=>x.id===b.dataset.cmdLink);closeCommand();await logEvent('open',{id:l.id,via:'command'});window.open(l.url,'_blank','noopener')})};input.oninput=draw;draw();setTimeout(()=>input.focus(),0)}
function closeCommand(){const ov=$('#command-overlay');ov.classList.add('hidden');ov.setAttribute('aria-hidden','true');ov.innerHTML=''}
function modal(html){$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal">${html}</div></div>`;$$('[data-close]',$('#modal-root')).forEach(b=>b.onclick=closeModal);$('.modal-backdrop').addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal()})}
function closeModal(){$('#modal-root').innerHTML=''}
function toast(text,{undo=false}={}){const el=document.createElement('div');el.className='toast';el.innerHTML=`${esc(text)}${undo?'<button class="undo">Undo</button>':''}`;$('#toast-root').appendChild(el);el.querySelector('.undo')?.addEventListener('click',()=>{undoDelete();el.remove()});setTimeout(()=>el.remove(),undo?8500:3500)}
async function cloudConfig(){if(!state.settings.supabaseUrl||!state.settings.supabaseAnonKey)throw new Error('Add Supabase URL and anon key first');return {url:state.settings.supabaseUrl,anonKey:state.settings.supabaseAnonKey}}
function showCloudAuthModal(){modal(`<form id="cloud-auth-form" class="p-6"><div class="flex justify-between"><div><p class="text-[9px] text-cyan-300 uppercase tracking-widest">Supabase auth</p><h2 class="text-white text-lg font-semibold mt-1">Cloud account</h2></div><button type="button" class="card-action" data-close><i class="ph ph-x"></i></button></div><div class="field mt-5"><label>Email</label><input name="email" type="email" required></div><div class="field mt-3"><label>Password</label><input name="password" type="password" minlength="6" required></div><div class="grid grid-cols-2 gap-2 mt-4"><button class="primary-btn" name="mode" value="signin">Sign in</button><button class="secondary-btn" name="mode" value="signup">Sign up</button></div></form>`);let mode='signin';$$('button[name="mode"]').forEach(b=>b.onclick=()=>mode=b.value);$('#cloud-auth-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const cfg=await cloudConfig(),r=mode==='signup'?await signUp(cfg,f.get('email'),f.get('password')):await signIn(cfg,f.get('email'),f.get('password'));if(!r.access_token&&mode==='signup'){closeModal();return toast('Account created. Confirm email, then sign in.')}state.settings.cloudSession=r;await setSetting('cloudSession',r);closeModal();updateSidebarStats();renderPage();toast('Cloud connected')}catch(err){toast(err.message)}}}
async function cloudSignOut(){state.settings.cloudSession=null;await setSetting('cloudSession',null);updateSidebarStats();renderPage();toast('Signed out')}
async function cloudPush(){try{const cfg=await cloudConfig(),token=state.settings.cloudSession?.access_token;if(!token)throw Error('Sign in first');await pushCloud(cfg,token,{links:state.links.map(cloudRow),collections:state.collections.map(cloudRow),workspaces:state.workspaces.map(cloudRow)});toast('Cloud push complete')}catch(e){toast(e.message)}}
async function cloudPull(){try{const cfg=await cloudConfig(),token=state.settings.cloudSession?.access_token;if(!token)throw Error('Sign in first');const d=await pullCloud(cfg,token);if(d.links?.length)await bulkPut('links',d.links.map(localRow));if(d.collections?.length)await bulkPut('collections',d.collections.map(localRow));if(d.workspaces?.length)await bulkPut('workspaces',d.workspaces.map(localRow));await refreshState();renderPage();toast('Cloud pull complete')}catch(e){toast(e.message)}}
function cloudRow(x){const {id,...data}=x;return {id,data,updated_at:new Date(x.updatedAt||Date.now()).toISOString()}}
function localRow(x){return {id:x.id,...(x.data||{})}}
async function confirmReset(){if(!confirm('Delete the entire local Smart Link Hub library? This cannot be undone.'))return;await resetAll();localStorage.clear();state.settings={interfaceGlow:true,autoMetadata:true,aiEnabled:true,compactCards:false,brokenScan:true,autoSnapshot:false,workerUrl:'',supabaseUrl:'',supabaseAnonKey:'',cloudSession:null};await seedCollections();await refreshState();navigate('home');toast('Local library reset')}
function registerPWA(){if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(console.warn);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.deferredInstall=e;$('#install-btn').classList.remove('hidden')});$('#install-btn').onclick=async()=>{if(!state.deferredInstall)return;state.deferredInstall.prompt();await state.deferredInstall.userChoice;state.deferredInstall=null;$('#install-btn').classList.add('hidden')}}
bootstrap().then(applySettings).catch(err=>{console.error(err);$('#dynamic-content').innerHTML=`<div class="p-8 text-red-300">Startup error: ${esc(err.message)}</div>`});
